class UserService:
    """Reads users through an in-memory cache. `db` is the source of truth."""

    def __init__(self, db):
        self.db = db
        self.cache = {}

    def get_user(self, user_id):
        """The user's record: a dict with "id", "name", "email" and "team"."""
        key = f"user:{user_id}"
        if key not in self.cache:
            self.cache[key] = self.db.get_user(user_id)
        return self.cache[key]

    def list_team(self, team):
        """The names of the users in `team`, in id order."""
        key = f"team:{team}"
        if key not in self.cache:
            self.cache[key] = [user["name"] for user in self.db.users_in_team(team)]
        return self.cache[key]

    def update_user(self, user_id, **fields):
        """Change fields of a user ("name", "email", "team") in the database."""
        self.db.update_user(user_id, fields)
        self.cache.pop(f"user:{user_id}", None)

