class FakeDB:
    """The source of truth: a few users, and a count of the reads the service has sent here."""
    def __init__(self, users):
        self.users = {user["id"]: dict(user) for user in users}
        self.reads = 0

    def get_user(self, user_id):
        self.reads += 1
        return dict(self.users[user_id])

    def users_in_team(self, team):
        self.reads += 1
        return [dict(user) for _, user in sorted(self.users.items()) if user["team"] == team]

    def update_user(self, user_id, fields):
        self.users[user_id].update(fields)
