class UserService:
    def __init__(self, db):
        self.db = db
        self.cache = {}

    def get_user(self, user_id):
        key = f"user:{user_id}"
        if key not in self.cache:
            self.cache[key] = self.db.get_user(user_id)
        return self.cache[key]

    def list_team(self, team):
        key = f"team:{team}"
        if key not in self.cache:
            self.cache[key] = [user["name"] for user in self.db.users_in_team(team)]
        return self.cache[key]

    def update_user(self, user_id, **fields):
        old_team = self.db.get_user(user_id)["team"]       # ask the database: this user may never have been cached
        self.db.update_user(user_id, fields)
        # forget everything that was built from this user: their record and the lists they were in, or are now in
        self.cache.pop(f"user:{user_id}", None)
        self.cache.pop(f"team:{old_team}", None)
        self.cache.pop(f"team:{fields.get('team', old_team)}", None)
